static class Getter<T>
{
    private static readonly ConcurrentDictionary<string, Func<T, object?>> Cache = new();

    public static Func<T, object?> For(string prop) => Cache.GetOrAdd(prop, p =>
    {
        var x = Expression.Parameter(typeof(T));
        var body = Expression.Convert(Expression.Property(x, p), typeof(object));
        return Expression.Lambda<Func<T, object?>>(body, x).Compile();
    });
}

public sealed class RatesProvider
{
    private FrozenDictionary<string, decimal> _rates = FrozenDictionary<string, decimal>.Empty;

    public decimal Get(string code) => Volatile.Read(ref _rates)[code];

    public void Reload(IEnumerable<KeyValuePair<string, decimal>> fresh) =>
        Volatile.Write(ref _rates, fresh.ToFrozenDictionary());
}

